+        # sends locally (see NixlBaseConnector.get_transfer_results).
         if (local_pcp_size > 1 and local_dcp_size == 1 and remote_dcp_size > 1) or (
             remote_pcp_size > 1 and remote_dcp_size == 1 and local_dcp_size > 1
         ):
